-- FIT OS public evaluation environment: synthetic data only.
-- Dedicated Supabase project; no other project is touched.
create table if not exists public.profiles (owner_id uuid not null default auth.uid() references auth.users(id), profile_id text primary key default gen_random_uuid()::text, name text, gender text, date_of_birth text, height_cm numeric, current_weight_kg numeric, avatar text, created_at text, updated_at text, active boolean);
alter table public.profiles enable row level security;
create policy evaluation_access on public.profiles for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.profiles to authenticated;
create table if not exists public.goals (owner_id uuid not null default auth.uid() references auth.users(id), goal_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, goal_type text, title text, description text, target_value numeric, unit text, start_value numeric, start_date text, target_date text, status text, created_at text, updated_at text);
alter table public.goals enable row level security;
create policy evaluation_access on public.goals for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.goals to authenticated;
create index on public.goals (profile_id);
create table if not exists public.exercises (owner_id uuid not null default auth.uid() references auth.users(id), exercise_id text primary key default gen_random_uuid()::text, name_ar text, name_en text, category text, muscle_group text, equipment text, exercise_type text, instructions text, active boolean);
alter table public.exercises enable row level security;
create policy evaluation_access on public.exercises for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.exercises to authenticated;
create table if not exists public.workout_plans (owner_id uuid not null default auth.uid() references auth.users(id), plan_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, plan_name text, description text, start_date text, end_date text, active boolean, created_at text, updated_at text);
alter table public.workout_plans enable row level security;
create policy evaluation_access on public.workout_plans for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.workout_plans to authenticated;
create index on public.workout_plans (profile_id);
create table if not exists public.workout_plan_exercises (owner_id uuid not null default auth.uid() references auth.users(id), plan_exercise_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, plan_id text, day_identifier text, exercise_id text, exercise_order numeric, target_sets numeric, target_reps numeric, target_duration numeric, target_distance numeric, target_rest_seconds numeric, target_rpe numeric, notes text);
alter table public.workout_plan_exercises enable row level security;
create policy evaluation_access on public.workout_plan_exercises for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.workout_plan_exercises to authenticated;
create index on public.workout_plan_exercises (profile_id);
create table if not exists public.workout_sessions (owner_id uuid not null default auth.uid() references auth.users(id), session_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, plan_id text, workout_date text, started_at text, finished_at text, duration_minutes numeric, session_rpe numeric, energy_level numeric, notes text, status text);
alter table public.workout_sessions enable row level security;
create policy evaluation_access on public.workout_sessions for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.workout_sessions to authenticated;
create index on public.workout_sessions (profile_id);
create table if not exists public.workout_sets (owner_id uuid not null default auth.uid() references auth.users(id), set_id text primary key default gen_random_uuid()::text, session_id text, profile_id text not null references public.profiles(profile_id) on delete cascade, exercise_id text, set_number numeric, target_reps numeric, actual_reps numeric, weight_kg numeric, duration_seconds numeric, distance numeric, rpe numeric, completed boolean, notes text);
alter table public.workout_sets enable row level security;
create policy evaluation_access on public.workout_sets for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.workout_sets to authenticated;
create index on public.workout_sets (profile_id);
create table if not exists public.nutrition_targets (owner_id uuid not null default auth.uid() references auth.users(id), nutrition_target_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, effective_date text, calorie_target numeric, protein_target_g numeric, carb_target_g numeric, fat_target_g numeric, water_target_ml numeric, notes text);
alter table public.nutrition_targets enable row level security;
create policy evaluation_access on public.nutrition_targets for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.nutrition_targets to authenticated;
create index on public.nutrition_targets (profile_id);
create table if not exists public.food_logs (owner_id uuid not null default auth.uid() references auth.users(id), food_log_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, date text, meal_type text, food_name text, quantity numeric, unit text, calories numeric, protein_g numeric, carbs_g numeric, fat_g numeric, water_ml numeric, notes text, created_at text);
alter table public.food_logs enable row level security;
create policy evaluation_access on public.food_logs for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.food_logs to authenticated;
create index on public.food_logs (profile_id);
create table if not exists public.body_measurements (owner_id uuid not null default auth.uid() references auth.users(id), measurement_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, date text, weight_kg numeric, waist_cm numeric, navel_cm numeric, chest_cm numeric, hips_cm numeric, neck_cm numeric, shoulders_cm numeric, left_arm_cm numeric, right_arm_cm numeric, left_thigh_cm numeric, right_thigh_cm numeric, left_calf_cm numeric, right_calf_cm numeric, body_fat_percent numeric, notes text);
alter table public.body_measurements enable row level security;
create policy evaluation_access on public.body_measurements for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.body_measurements to authenticated;
create index on public.body_measurements (profile_id);
create table if not exists public.recovery_logs (owner_id uuid not null default auth.uid() references auth.users(id), recovery_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, date text, sleep_hours numeric, sleep_quality numeric, energy_level numeric, soreness numeric, stress_level numeric, resting_heart_rate numeric, notes text);
alter table public.recovery_logs enable row level security;
create policy evaluation_access on public.recovery_logs for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.recovery_logs to authenticated;
create index on public.recovery_logs (profile_id);
create table if not exists public.weekly_reviews (owner_id uuid not null default auth.uid() references auth.users(id), review_id text primary key default gen_random_uuid()::text, profile_id text not null references public.profiles(profile_id) on delete cascade, week_start text, week_end text, workout_completion_percent numeric, average_weight numeric, weight_change numeric, average_calories numeric, average_protein numeric, average_sleep numeric, progress_summary text, recommendation text, created_at text);
alter table public.weekly_reviews enable row level security;
create policy evaluation_access on public.weekly_reviews for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.weekly_reviews to authenticated;
create index on public.weekly_reviews (profile_id);
create table if not exists public.app_settings (owner_id uuid not null default auth.uid() references auth.users(id), setting_key text primary key, setting_value text, updated_at text);
alter table public.app_settings enable row level security;
create policy evaluation_access on public.app_settings for all to authenticated using ((select auth.uid()) = owner_id) with check ((select auth.uid()) = owner_id);
grant select,insert,update,delete on public.app_settings to authenticated;
alter table public.workout_sessions add unique(session_id,profile_id);
alter table public.workout_sets add constraint session_profile_fk foreign key(session_id,profile_id) references public.workout_sessions(session_id,profile_id);
alter table public.workout_plans add unique(plan_id,profile_id);
alter table public.workout_plan_exercises add constraint plan_profile_fk foreign key(plan_id,profile_id) references public.workout_plans(plan_id,profile_id);
alter table public.recovery_logs add unique(profile_id,date);